#!/usr/bin/env python3
"""Extract all original shell data definitions, with explicit native scalar order.
No code is inferred. Source line numbers and sizes are retained in a manifest.
Text font/masks already owned by shell_text.s remain there to avoid duplication.
"""
from pathlib import Path
import re,json,ast
root=Path(__file__).resolve().parent.parent
lines=(root/'reference/src/shell.s').read_text().splitlines()
code=[l.split(';')[0].strip() for l in lines]
out=['# Complete RC6 shell data, generated by tools/port-shell-data.py.', '# Numeric words/pointers native; commander CASH remains serialized BE32.', '.data','.globl shell_data_begin','shell_data_begin:']
records=[];owner=None;skip=False;offset=0
for i,line in enumerate(code):
 m=re.match(r'(\w+):\s*(.*)',line)
 if m:
  name,tail=m.groups()
  probe=tail or next((x for x in code[i+1:] if x),'')
  if not re.match(r'\.(data[124]|space|ascii)\b',probe):owner=None;skip=False;continue
  owner=name;skip=name in ('asm_font','text_masks','cheat_actions')
  records.append(dict(name=name,line=i+1,native_file=('src/shell_cheats.s' if name=='cheat_actions' else 'src/shell_text.s') if skip else 'src/shell_data.s',offset=None if skip else offset,size=0,directives=[]))
  if not skip:out.extend(['.globl '+name,name+':'])
  line=tail
 if not line:continue
 if line.startswith('.align'):
  if not skip:out.append(line);offset=(offset+3)&~3
  continue
 if not owner:continue
 op,*rest=line.split(None,1)
 if op not in ('.data1','.data2','.data4','.space','.ascii'):continue
 arg=rest[0];n=0
 if op=='.ascii':n=len(ast.literal_eval('b'+arg))
 elif op=='.space':n=int(arg,0)
 else:n=int(op[-1])*len(arg.split(','))
 records[-1]['size']+=n;records[-1]['directives'].append(dict(line=i+1,source=line))
 if skip:continue
 if owner=='asm_commander' and op=='.data4':
  assert arg=='1000';out.append(' .byte 0,0,3,232')
 else:out.append(' '+{'.data1':'.byte','.data2':'.word','.data4':'.long'}.get(op,op)+' '+arg)
 offset+=n
out+=['.globl shell_data_end','shell_data_end:']
(root/'src/shell_data.s').write_text('\n'.join(out)+'\n')
(root/'docs/R3-SHELL-DATA.json').write_text(json.dumps(dict(objects=records,native_bytes=offset),indent=2)+'\n')
print(len(records),'source data labels;',offset,'bytes in central data module')
